    p_j^t(z)\leq p_j^*(z)+(p_j^t(z)-p_j^*(z)) \leq p_j^*(z)+ |p_j^t(z)-p_j^*(z)|\leq p_j^*(z)+\sum_t |p_j^t(z)-p_j^*(z)|
\end{equation}
thus, $\sup_t p_j^t$ is integrable because the right term is integrable as well. Then, observe that:

\[ \Vert \nabla\ell_{j,t} \Vert |p^*_j(z)-p^t_j(z)| =  \Vert \nabla\ell_{j,t} \Vert 1_{p^*_j(z)< p^t_j(z)}|p^*_j(z)-p^t_j(z)|+ \Vert \nabla\ell_{j,t} \Vert 1_{p^*_j(z)\geq  p^t_j(z)}|p^*_j(z)-p^t_j(z)|\]

Then, the left term is bounded because:

\begin{equation}
    \Vert \nabla\ell_{j,t} \Vert 1_{p^*_j(z)< p^t_j(z)}|p^*_j(z)-p^t_j(z)|\leq \Vert \nabla\ell_{j,t} \Vert 1_{p^*_j(z)< p^t_j(z)}p^t_j(z) \leq \Vert \nabla\ell_{j,t} \Vert 1_{p^*_j(z)< p^t_j(z)}\sup_t p^t_j(z)
\end{equation}

\[\int \sum_t   1_{p^*_j(z)\geq  p^t_j(z)}(p^*_j(z)-p^t_j(z))\,dz\leq \int \sum_t   1_{p^*_j(z)=  p^t_j(z)}|p^*_j(z)-p^t_j(z)|\,dz<\infty\]

In particular:
\[\int \sum_t   1_{p^*_j(z)\geq  p^t_j(z)}p^*_j(z)\,dz<\infty\]

It implies that $\sum_t   1_{p^*_j(z)\geq  p^t_j(z)}$ is almost surely finite, and, a.s. $\forall z,\exists t_0, p^*_j(z)\leq p^{t_0}_j(z)$. In particular this implies that a.s.:
\[\forall z, p^*_j(z)\leq \sup_t p_j^t(z)\]

