By $L$-smoothness:
\begin{align}
\mathcal{L}(\Theta_j^{t+1})\leq\mathcal{L}(\Theta_j^t)&+\nabla\mathcal{L}(\Theta_j^t)^{T}(\Theta^{t+1}_{j}-\Theta_{j}^t)+\frac{L}{2}\Vert\Theta_{j}^{t+1}-\Theta_{j}^t\Vert^{2}
\end{align}
Substituting $\Theta_{j}^{t+1}-\Theta_{j}^{t}$ on the right:
\begin{align}
\mathcal{L}(\Theta_j^{t+1})&\leq\mathcal{L}(\Theta_j^t)-\eta_t\nabla\mathcal{L}(\Theta_j^t)^{T} \nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)+\frac{L\eta_t^2}{2}\Vert\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)\Vert^{2}
\end{align}




Taking the expectation w.r.t. $Z_{j-1}^t$ which has a density $p_{j-1}^t$, we get:
\begin{align*}
\mathbb{E}_{p^t_{j-1}}[\mathcal{L}(\Theta_j^{t+1})]&\leq\mathcal{L}(\Theta_j^t)-\eta_t\nabla\mathcal{L}(\Theta_j^t)^{T}\mathbb{E}_{p_{j-1}^t}[\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)]
+\frac{L\eta_t^2}{2}\mathbb{E}_{p_{j-1}^t}\big[\Vert\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)\Vert^{2}\big]
\end{align*}

From Assumption 3, we obtain that:
\begin{equation}
    \frac{L\eta_t^2}{2}\mathbb{E}_{p_{j-1}^t}\big[\Vert \nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)\Vert^{2}\big]\leq \frac{L\eta_t^2G}{2}
\end{equation}


Then, as a side computation, observe that:

\begin{align}
\Vert \mathbb{E}_{p_{j-1}^t}\big[\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)\big]-\nabla\mathcal{L}(\Theta_j^t)\Vert&=\Vert \int \nabla \ell(z,\Theta_j^t)p^t_{j-1}(z)\,d z -\int \nabla \ell(z,\Theta_j^t)p^*_{j-1}(z)\,d z\Vert\\
&\leq   \int \Vert\nabla \ell(z,\Theta_j^t)\Vert ~ |p^t_{j-1}(z)-p^*_{j-1}(z)|\,d z\\
&=  \int \big(\Vert\nabla \ell(z,\Theta_j^t)\Vert\sqrt{|p^t_{j-1}(z)-p^*_{j-1}(z)|}\big) ~ \sqrt{|p^t_{j-1}(z)-p^*_{j-1}(z)|}\,d z\\
\end{align}
Let us apply the Cauchy-Swchartz inequality, we obtain:

\begin{align}
\Vert \mathbb{E}_{p_{j-1}^t}\big[\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)\big]-\nabla\mathcal{L}(\Theta_j^t)\Vert&\leq \sqrt{\int \Vert\nabla \ell(z,\Theta_j^t)\Vert^2 |p^t_{j-1}(z)-p^*_{j-1}(z)|\,d z} \sqrt{\int |p^t_{j-1}(z)-p^*_{j-1}(z)|\,d z }\\
&= \sqrt{\int \Vert\nabla \ell(z,\Theta_j^t)\Vert^2 |p^t_{j-1}(z)-p^*_{j-1}(z)|\,d z} \sqrt{c_{j-1}^t}
\end{align}

Then, observe that:

\begin{align}
\int \Vert\nabla \ell(z,\Theta_j^t)\Vert^2 |p^t_{j-1}(z)-p^*_{j-1}(z)|\,d z &\leq  \int \Vert\nabla \ell(z,\Theta_j^t)\Vert^2 \big(p^t_{j-1}(z)+p^*_{j-1}(z)\big)\,d z\\
&=\mathbb{E}_{p^t_{j-1}}[ \Vert\nabla \ell(Z_{j-1},\Theta_j^t)\Vert^2 ]+\mathbb{E}_{p^*_{j-1}}[ \Vert\nabla \ell(Z_{j-1},\Theta_j^t)\Vert^2 ]\\
&\leq 2G
\end{align}

The last inequality follows from Lemma 4.1 and Assumption 3.


Then, using again Cauchy-Schwartz inequality:
\begin{align}
\bigg|\Vert\nabla\mathcal{L}(\Theta_j^t)\Vert^2- \nabla\mathcal{L}(\Theta_j^t)^{T}\mathbb{E}_{p_{j-1}^t}[\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)]\bigg|
&=\bigg|\nabla\mathcal{L}(\Theta_j^t)^T\big(\nabla\mathcal{L}(\Theta_j^t)-\mathbb{E}_{p_{j-1}^t}[\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)]\big)\bigg|\\
&\leq \Vert \nabla \mathcal{L}(\Theta^t_j)\Vert~\Vert \mathbb{E}_{p_{j-1}^t}\big[\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)\big]-\nabla\mathcal{L}(\Theta_j^t)\Vert \\
&\leq \Vert \nabla \mathcal{L}(\Theta^t_j)\Vert \sqrt{2Gc^t_{j-1}}

\end{align}

Then, taking the expectation leads to

\begin{align}
\big|\mathbb{E}\bigg[\Vert\nabla\mathcal{L}(\Theta_j^t)\Vert^2- \nabla\mathcal{L}(\Theta_j^t)^{T}\mathbb{E}_{p_{j-1}^t}[\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)]\bigg]\big|&\leq \mathbb{E}[\bigg|\Vert\nabla\mathcal{L}(\Theta_j^t)\Vert^2- \nabla\mathcal{L}(\Theta_j^t)^{T}\mathbb{E}_{p_{j-1}^t}[\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)]\bigg|]\\
&\leq \mathbb{E}[\Vert\nabla \mathcal{L}(\Theta^t_j)\Vert] \sqrt{2Gc^t_{j-1}}\\
&\leq \sqrt{ \mathbb{E}[\Vert\nabla \mathcal{L}(\Theta^t_j)\Vert^2] }\sqrt{2Gc^t_{j-1}}\\

\end{align}
However, observe that by Lemma 4.1 and Jensen inequality:

\begin{align}
\Vert \nabla\mathcal{L}(\Theta_j^t)\Vert^2 =\Vert \mathbb{E}_{p^*_j}[\nabla_{\Theta_j} \ell(Z,\Theta_j^t)]\Vert^2\leq \mathbb{E}_{p^*_j}[ \Vert \nabla_{\Theta_j} \ell(Z,\Theta_j^t)\Vert^2]\leq G
\end{align}

Combining this inequality and Assumption 3, we get:
\begin{align*}
\mathbb{E}[\mathcal{L}(\Theta_j^{t+1})]\leq\mathbb{E}[\mathcal{L}(\Theta_j^{t})]-\eta_t\big(\mathbb{E}[\Vert\nabla\mathcal{L}(\Theta_j^t)\Vert^2]-\sqrt{2}Gc^t_{j-1}\big)+\frac{LG}{2}\eta_t^2\,,
\end{align*}

