&=\bigg|\nabla\mathcal{L}(\Theta_j^t)^T\big(\nabla\mathcal{L}(\Theta_j^t)-\mathbb{E}_{p_{j-1}^t}[\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)]\big)\bigg|\\
&\leq \Vert \nabla \mathcal{L}(\Theta^t_j)\Vert~\Vert \mathbb{E}_{p_{j-1}^t}\big[\nabla_{\Theta_j} \ell(Z_{j-1}^t;\Theta_j^t)\big]-\nabla\mathcal{L}(\Theta_j^t)\Vert \\
&\leq \Vert \nabla \mathcal{L}(\Theta^t_j)\Vert \sqrt{2Gc^t_{j-1}}

\end{align}

