\small
\caption{DGL Parallel Implementation\label{_algo:basic_parallel}}
  \SetAlgoLined
  \DontPrintSemicolon
 \KwIn{Stream $\mathcal{S}\triangleq\{(x_0^t,y^t)\}_{t\leq T}$ of samples or mini-batches;}
\textbf{Initialize} Parameters $\{\theta_j,\gamma_j\}_{j\leq J}$\\
Worker 0:\;
\For {$x_0^t \in \mathcal{S}$}{
$x^t_1 \leftarrow f_{\theta^t_{0}}(x^t_{0})$\\
Send $x_0^t$ to worker $1$\;
Compute $\nabla_{(\gamma_1,\theta_1)}\hat{ \mathcal{L}}(y^t,x^t_0;\gamma^t_0,\theta^t_0)$\;
$(\theta^{t+1}_0,\gamma^{t+1}_0)\leftarrow$ Step of parameters $(\theta^t_0,\gamma^t_0)$}
Worker $j$:\;
\For{$t \in 0 ... T$}{
Wait until $x^t_{j-1}$ is available\;
$x^t_j \leftarrow f_{\theta^t_{j-1}}(x^t_{j-1})$ \\
Compute $\nabla_{(\gamma_j,\theta_j)}\hat{ \mathcal{L}}(y^t,x^t_j;\gamma^t_j,\theta^t_j)$\\
Send $x^t_{j}$ to worker $x^t_{j+1}$\\
$(\theta^{t+1}_j,\gamma^{t+1}_j)\leftarrow$ Step of parameters $(\theta^t_j,\gamma^t_j)$}

